void draw_box(int y, int x, int w, int h, int bold) {
    // Draw box using ACS characters
    // Top border: ACS_ULCORNER + HLINE*(w-2) + ACS_URCORNER
    // Sides: VLINE
    // Bottom border: LL + HLINE...
    // If bold, use bold attribute?
    if (bold) attron(A_BOLD);
    // Use ACS
    mvaddch(y, x, ACS_ULCORNER);
    for (int i=1;i<w-1;i++) mvaddch(y, x+i, ACS_HLINE);
    mvaddch(y, x+w-1, ACS_URCORNER);
    for (int r=1;r<h-1;r++) {
        mvaddch(y+r, x, ACS_VLINE);
        mvaddch(y+r, x+w-1, ACS_VLINE);
    }
    mvaddch(y+h-1, x, ACS_LLCORNER);
    for (int i=1;i<w-1;i++) mvaddch(y+h-1, x+i, ACS_HLINE);
    mvaddch(y+h-1, x+w-1, ACS_LRCORNER);
    if (bold) attroff(A_BOLD);
}

void draw_box_with_date(int y, int x, int w, int h, const char *date_str, int bold, int color_fg_pair) {
    // w = box_w (clock box), h = box_h (clock box)
    // date_str length
    int date_len = strlen(date_str);
    int date_box_w = date_len + 2;
    int date_box_h = 3;
    // Compute left_q for bottom border that includes date top
    // Total width w, q count = w-2 = inner width? Actually for box, top border has w-2 q's.
    // Bottom border split: left_q + date_len + right_q = w-2 -2? Wait we need to compute:
    // Bottom line: m + Q1 + l + Q2 + k + Q3 + j = w
    // Q1+Q2+Q3 = w-4, Q2=date_len
    // So left_q = (w - date_box_w)/2 -1? Let's compute using earlier observed: w=54, date_box_w=12, left_q=20
    // (w - date_box_w)/2 =21, minus1=20 matches.
    int left_q = (w - date_box_w)/2 -1;
    if (left_q<0) left_q=0;
    int right_q = w - 4 - left_q - date_len;
    if (right_q<0) right_q=0;

    // Draw top
    if (bold) attron(A_BOLD);
    mvaddch(y, x, ACS_ULCORNER);
    for (int i=1;i<w-1;i++) mvaddch(y, x+i, ACS_HLINE);
    mvaddch(y, x+w-1, ACS_URCORNER);
    // Sides for middle rows (except last)
    for (int r=1;r<h-1;r++) {
        mvaddch(y+r, x, ACS_VLINE);
        mvaddch(y+r, x+w-1, ACS_VLINE);
    }
    // Bottom border with notch
    mvaddch(y+h-1, x, ACS_LLCORNER);
    for (int i=0;i<left_q;i++) mvaddch(y+h-1, x+1+i, ACS_HLINE);
    mvaddch(y+h-1, x+1+left_q, ACS_ULCORNER); // l for date top left
    for (int i=0;i<date_len;i++) mvaddch(y+h-1, x+1+left_q+1+i, ACS_HLINE);
    mvaddch(y+h-1, x+1+left_q+1+date_len, ACS_URCORNER);
    for (int i=0;i<right_q;i++) mvaddch(y+h-1, x+1+left_q+1+date_len+1+i, ACS_HLINE);
    mvaddch(y+h-1, x+w-1, ACS_LRCORNER);
    if (bold) attroff(A_BOLD);

    // Draw date box sides and bottom
    int date_x = x + left_q +1;
    int date_y = y + h -1;
    // date_y is line of top border we already drew partially, but date content is at date_y+1
    // Sides
    if (bold) attron(A_BOLD);
    mvaddch(date_y+1, date_x, ACS_VLINE);
    mvaddch(date_y+1, date_x+date_box_w-1, ACS_VLINE);
    mvaddch(date_y+2, date_x, ACS_LLCORNER);
    for (int i=1;i<date_box_w-1;i++) mvaddch(date_y+2, date_x+i, ACS_HLINE);
    mvaddch(date_y+2, date_x+date_box_w-1, ACS_LRCORNER);
    if (bold) attroff(A_BOLD);

    // Date string itself
    if (bold) attron(A_BOLD);
    attron(COLOR_PAIR(color_fg_pair));
    mvaddstr(date_y+1, date_x+1, date_str);
    attroff(COLOR_PAIR(color_fg_pair));
    if (bold) attroff(A_BOLD);
}

