                    snprintf(date_buf, sizeof(date_buf), "%s [%s]", tmp, ampm);
                } else {
                    strftime(date_buf, sizeof(date_buf), fmt, &tm_now);
                }
                int date_len = strlen(date_buf);
                int date_x, date_y;
                if (opts.centered) {
                    // Date centered relative to clock
                    date_x = draw_x + (clock_w - date_len)/2;
                    date_y = draw_y + clock_h;
                } else {
                    // Original non-centered date appears below clock, slightly indented? In earlier capture without -c, date appeared at x + (clock_w - date_len)/2? Let's see: Without -c, clock at 0,0, date at (clock_w - date_len)/2 centered under clock? In capture with no -c, date was at x=... Let's check earlier non-centered capture: without -c, clock at left, date at x = (clock_w - date_len)/2? In first capture without -c and without box, date was at column maybe centered under clock? Let's assume same.
                    date_x = draw_x + (clock_w - date_len)/2;
                    date_y = draw_y + clock_h;
                }
                // Draw date with fg color and bold?
                int col = (opts.color>=0 && opts.color<=7) ? opts.color : 2;
                int pair_fg = col+10;
                if (opts.bold) attron(A_BOLD);
                attron(COLOR_PAIR(pair_fg));
                mvaddstr(date_y, date_x, date_buf);
                attroff(COLOR_PAIR(pair_fg));
                if (opts.bold) attroff(A_BOLD);
            }
        }

        refresh();

        // Handle input
        int ch = getch();
        if (ch != ERR) {
            if (opts.screensaver) {
                if (!opts.noquit) break;
            }
            // Convert to lower for case-insensitive?
            int lc = tolower(ch);
            if (lc=='q') {
                if (!opts.noquit) break;
            } else if (lc=='c') {
                opts.centered = !opts.centered;
                if (opts.centered) {
                    int total_w = opts.show_box ? box_w : clock_w;
                    int total_h = opts.show_box ? box_h : clock_h;
                    if (!opts.hide_date) {
                        if (opts.show_box) total_h +=2;
                        else total_h+=1;
                    }
                    pos_x = (term_w - total_w)/2;
                    pos_y = (term_h - total_h)/2;
                    if (pos_x<0) pos_x=0;
                    if (pos_y<0) pos_y=0;
                }
            } else if (lc=='x') {
                opts.show_box = !opts.show_box;
                compute_clock_size();
                if (opts.centered) {
                    int total_w = opts.show_box ? box_w : clock_w;
                    int total_h = opts.show_box ? box_h : clock_h;
                    if (!opts.hide_date) {
                        if (opts.show_box) total_h+=2;
                        else total_h+=1;
                    }
                    pos_x = (term_w - total_w)/2;
                    pos_y = (term_h - total_h)/2;
                }
            } else if (lc=='b') {
                opts.bold = !opts.bold;
            } else if (lc>='0' && lc<='7') {
                opts.color = lc - '0';
            } else if (lc=='s') {
                opts.show_seconds = !opts.show_seconds;
                compute_clock_size();
                if (opts.centered) {
                    int total_w = opts.show_box ? box_w : clock_w;
                    int total_h = opts.show_box ? box_h : clock_h;
                    if (!opts.hide_date) {
                        if (opts.show_box) total_h+=2;
                        else total_h+=1;
                    }
                    pos_x = (term_w - total_w)/2;
                    pos_y = (term_h - total_h)/2;
                }
            } else if (lc=='t') {
                opts.twelve = !opts.twelve;
            } else if (lc=='r') {
                opts.rebound = !opts.rebound;
            } else if (lc=='h' || lc=='k' || lc=='l' || lc=='j') {
                if (!opts.centered) {
                    if (lc=='h') { if (pos_x>0) pos_x--; }
                    if (lc=='l') { if (pos_x+ (opts.show_box?box_w:clock_w) < term_w) pos_x++; }
                    if (lc=='j') { if (pos_y+ (opts.show_box?box_h:clock_h) < term_h) pos_y++; }
                    if (lc=='k') { if (pos_y>0) pos_y--; }
                }
            }
        }

        // Rebound movement
        if (opts.rebound && !opts.centered) {
            // Move
            pos_x += dir_x;
            pos_y += dir_y;
            int cur_w = opts.show_box ? box_w : clock_w;
            int cur_h = opts.show_box ? box_h : clock_h;
            if (!opts.hide_date) {
                if (opts.show_box) cur_h +=2;
                else cur_h+=1;
            }
            if (pos_x <=0 || pos_x+cur_w >= term_w) {
                dir_x = -dir_x;
                pos_x += dir_x;
            }
            if (pos_y <=0 || pos_y+cur_h >= term_h) {
                dir_y = -dir_y;
                pos_y += dir_y;
            }
        } else if (opts.rebound && opts.centered) {
            // Even when centered, rebound still moves? Let's implement same but starting centered.
            pos_x += dir_x;
            pos_y += dir_y;
            int cur_w = opts.show_box ? box_w : clock_w;
            int cur_h = opts.show_box ? box_h : clock_h;
            if (!opts.hide_date) {
                if (opts.show_box) cur_h+=2;
                else cur_h+=1;
            }
            if (pos_x <=0 || pos_x+cur_w >= term_w) {
                dir_x = -dir_x;
                pos_x += dir_x;
            }
            if (pos_y <=0 || pos_y+cur_h >= term_h) {
                dir_y = -dir_y;
                pos_y += dir_y;
            }
        }

        // Delay
        struct timespec ts;
        ts.tv_sec = opts.delay_sec;
        ts.tv_nsec = opts.delay_nsec;
        // If both zero, set minimal?
        if (ts.tv_sec==0 && ts.tv_nsec==0) {
            ts.tv_sec=1;
        }
        nanosleep(&ts, NULL);
    }

    cleanup();
    return 0;
}
C
"}

