                pos_x += dir_x;
            }
            if (pos_y <=0 || pos_y+cur_h >= term_h) {
                dir_y = -dir_y;
                pos_y += dir_y;
            }
        } else if (opts.rebound && opts.centered) {
            // Even when centered, rebound still moves? Let's implement same but starting centered.
            pos_x += dir_x;
            pos_y += dir_y;
            int cur_w = opts.show_box ? box_w : clock_w;
