            }
            if (pos_x <=0 || pos_x+cur_w >= term_w) {
                dir_x = -dir_x;
                pos_x += dir_x;
            }
            if (pos_y <=0 || pos_y+cur_h >= term_h) {
                dir_y = -dir_y;
                pos_y += dir_y;
            }
        }

        // Delay
        struct timespec ts;
        ts.tv_sec = opts.delay_sec;
        ts.tv_nsec = opts.delay_nsec;
        // If both zero, set minimal?
        if (ts.tv_sec==0 && ts.tv_nsec==0) {
            ts.tv_sec=1;
        }
        nanosleep(&ts, NULL);
    }

    cleanup();
    return 0;
}
