cat /tmp/impl.c | grep -n "ttyscr"
# Our implementation tries to use stdscr global but we also set ttyscr = stdscr? That may cause issues. Also we have cleanup that calls endwin after already? Our binary segfaulted.
# Let's fix implementation.

cat > /tmp/impl2.c <<'C'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <getopt.h>
#include <time.h>
#include <sys/stat.h>
#include <errno.h>
#include <ncurses.h>
#include <signal.h>
#include <locale.h>
#include <ctype.h>
#include <stdbool.h>
#include <math.h>

#define VERSION_STR "TTY-Clock 2 \xc2\xa9 devel version\n"
#define INFO_STR "TTY-Clock 2 \xc2\xa9 by Martin Duquesnoy (xorg62@gmail.com), Grey (grey@greytheory.net)\n"

static const char *usage_str =
"usage : tty-clock [-iuvsScbtrahDBxn] [-C [0-7]] [-f format] [-d delay] [-a nsdelay] [-T tty] \n"
"    -s            Show seconds                                   \n"
"    -S            Screensaver mode                               \n"
"    -x            Show box                                       \n"
"    -c            Set the clock at the center of the terminal    \n"
"    -C [0-7]      Set the clock color                            \n"
"    -b            Use bold colors                                \n"
"    -t            Set the hour in 12h format                     \n"
"    -u            Use UTC time                                   \n"
"    -T tty        Display the clock on the specified terminal    \n"
"    -r            Do rebound the clock                           \n"
"    -f format     Set the date format                            \n"
"    -n            Don't quit on keypress                         \n"
"    -v            Show tty-clock version                         \n"
"    -i            Show some info about tty-clock                 \n"
"    -h            Show this page                                 \n"
"    -D            Hide date                                      \n"
"    -B            Enable blinking colon                          \n"
"    -d delay      Set the delay between two redraws of the clock. Default 1s. \n"
"    -a nsdelay    Additional delay between two redraws in nanoseconds. Default 0ns.\n";

typedef struct {
    int show_seconds;
    int screensaver;
    int show_box;
    int centered;
    int color; // 0-7, -1 means default (2)
    int bold;
    int twelve;
    int utc;
    int rebound;
    int hide_date;
    int blink;
    int noquit;
    char *date_format;
    long delay_sec;
    long delay_nsec;
    char *tty_path;
} options_t;

static options_t opts;

static const char *digits[10][5] = {
    {"######","##..##","##..##","##..##","######"},
    {"....##","....##","....##","....##","....##"},
    {"######","....##","######","##....","######"},
    {"######","....##","######","....##","######"},
    {"##..##","##..##","######","....##","....##"},
    {"######","##....","######","....##","######"},
    {"######","##....","######","##..##","######"},
    {"######","....##","....##","....##","....##"},
    {"######","##..##","######","##..##","######"},
    {"######","##..##","######","....##","######"}
};
static const char *colon_pat[5] = {"..","##","..","##",".."};

static int term_w, term_h;
static int clock_w, clock_h;
static int box_w, box_h;
static int pos_x, pos_y;
static int dir_x, dir_y;

static SCREEN *ttyscr = NULL;
static FILE *tty_out = NULL;

void cleanup() {
    if (ttyscr) {
        // if we used newterm, need to endwin and delscreen
        endwin();
        delscreen(ttyscr);
        ttyscr=NULL;
    } else {
        // stdscr case
        if (isendwin()==FALSE) endwin();
    }
    if (tty_out) {
        fclose(tty_out);
        tty_out=NULL;
    }
}

void init_curses() {
    if (opts.tty_path) {
        struct stat st;
        if (stat(opts.tty_path, &st)!=0) {
            fprintf(stderr, "tty-clock: error: couldn't stat '%s': %s.\n", opts.tty_path, strerror(errno));
            exit(1);
        }
        if (!S_ISCHR(st.st_mode)) {
            fprintf(stderr, "tty-clock: error: '%s' doesn't appear to be a character device.\n", opts.tty_path);
            exit(1);
        }
        tty_out = fopen(opts.tty_path, "r+");
        if (!tty_out) {
            fprintf(stderr, "tty-clock: error: '%s' couldn't be opened: %s.\n", opts.tty_path, strerror(errno));
            exit(1);
        }
        ttyscr = newterm(NULL, tty_out, tty_out);
        if (ttyscr==NULL) {
            fprintf(stderr, "%s: ttyclock.c:53: init: Assertion `ttyclock.ttyscr != NULL' failed.\n", "executable");
            abort();
        }
        set_term(ttyscr);
        cbreak();
        noecho();
        nodelay(stdscr, TRUE);
        keypad(stdscr, TRUE);
        curs_set(0);
        if (has_colors()) {
            start_color();
            for (int i=0;i<8;i++) {
                init_pair(i+1, COLOR_WHITE, i);
                init_pair(i+10, i, COLOR_BLACK);
            }
        }
        clear();
    } else {
        // initscr will handle errors itself and print "Error opening terminal: unknown." and exit(1)
        // So we just call it and if fails, it will exit. To avoid double handling, we call initscr.
        // Note: initscr may call exit itself on failure, so we won't reach next.
        initscr();
        // If initscr succeeded, stdscr is set
        cbreak();
        noecho();
        nodelay(stdscr, TRUE);
        keypad(stdscr, TRUE);
        curs_set(0);
        if (has_colors()) {
            start_color();
            for (int i=0;i<8;i++) {
                init_pair(i+1, COLOR_WHITE, i);
                init_pair(i+10, i, COLOR_BLACK);
            }
        }
        clear();
    }
}

void compute_clock_size() {
    if (opts.show_seconds) {
        clock_w = 51;
    } else {
        clock_w = 32;
    }
    clock_h = 5;
    if (opts.show_box) {
        box_w = clock_w + 3;
        box_h = clock_h + 2;
    } else {
        box_w = clock_w;
        box_h = clock_h;
    }
}

void draw_digit(int y, int x, int digit, int pair_bg, int bold) {
    if (digit<0||digit>9) return;
    for (int r=0;r<5;r++) {
        const char *pat = digits[digit][r];
        for (int c=0;c<6;c++) {
            if (pat[c]=='#') {
                if (bold) attron(A_BOLD);
                // Original used blink (5m) for bold? We'll use A_BLINK to get 5m
                if (bold) attron(A_BLINK);
                attron(COLOR_PAIR(pair_bg));
                mvaddch(y+r, x+c, ' ');
                attroff(COLOR_PAIR(pair_bg));
                if (bold) attroff(A_BLINK);
                if (bold) attroff(A_BOLD);
            }
        }
    }
}
void draw_colon(int y, int x, int pair_bg, int pair_fg, int bold, int visible) {
    for (int r=0;r<5;r++) {
        if (colon_pat[r][0]=='#' || colon_pat[r][1]=='#') {
            // actually colon has "##" at row1 and3, width 2
            if (colon_pat[r][0]=='.') continue;
            for (int c=0;c<2;c++) {
                if (colon_pat[r][c]!='#') continue;
                if (visible) {
                    if (bold) attron(A_BOLD);
                    if (bold) attron(A_BLINK);
                    attron(COLOR_PAIR(pair_bg));
                    mvaddch(y+r, x+c, ' ');
                    attroff(COLOR_PAIR(pair_bg));
                    if (bold) attroff(A_BLINK);
                    if (bold) attroff(A_BOLD);
                } else {
                    if (bold) attron(A_BOLD);
                    if (bold) attron(A_BLINK);
                    attron(COLOR_PAIR(pair_fg));
                    mvaddch(y+r, x+c, ' ');
                    attroff(COLOR_PAIR(pair_fg));
                    if (bold) attroff(A_BLINK);
                    if (bold) attroff(A_BOLD);
                }
            }
        }
    }
}
void draw_clock_at(int y, int x, struct tm *tm, int blink_vis) {
    int hour = tm->tm_hour;
    if (opts.twelve) {
        int h = hour %12;
        if (h==0) h=12;
        hour=h;
    }
    int min = tm->tm_min;
    int sec = tm->tm_sec;
    int col = (opts.color>=0 && opts.color<=7)?opts.color:2;
    int pair_bg = col+1;
    int pair_fg = col+10;
    int ht = hour/10;
    int ho = hour%10;
    int mt = min/10;
    int mo = min%10;
    int st = sec/10;
    int so = sec%10;
    if (opts.show_seconds) {
