typedef struct {
    int show_seconds;
    int screensaver;
    int show_box;
    int centered;
    int color; // -1 default
    int bold;
    int twelve;
    int utc;
    int rebound;
    int hide_date;
    int blink;
    int noquit;
    char *date_format;
    long delay_sec;
    long delay_nsec;
    char *tty_path;
} options_t;

static options_t opts;

static const char *digits[10][5] = {
    {"######","##..##","##..##","##..##","######"},
    {"....##","....##","....##","....##","....##"},
    {"######","....##","######","##....","######"},
    {"######","....##","######","....##","######"},
    {"##..##","##..##","######","....##","....##"},
    {"######","##....","######","....##","######"},
    {"######","##....","######","##..##","######"},
    {"######","....##","....##","....##","....##"},
    {"######","##..##","######","##..##","######"},
    {"######","##..##","######","....##","######"}
};
static const char *colon_pat[5] = {"..","##","..","##",".."};

static int term_w, term_h;
static int clock_w, clock_h;
static int box_w, box_h;
static int pos_x, pos_y;
static int dir_x, dir_y;

static SCREEN *ttyscr = NULL;
static FILE *tty_out = NULL;

void cleanup() {
    if (ttyscr) {
        endwin();
        delscreen(ttyscr);
        ttyscr=NULL;
    } else {
        if (!isendwin()) endwin();
    }
    if (tty_out) {
        fclose(tty_out);
        tty_out=NULL;
    }
}

void compute_clock_size() {
    clock_w = opts.show_seconds ? 51 : 32;
    clock_h = 5;
    if (opts.show_box) {
        box_w = clock_w + 3;
        box_h = clock_h + 2;
    } else {
        box_w = clock_w;
        box_h = clock_h;
    }
}

void draw_digit(int y,int x,int digit,int pair_bg,int bold) {
    if (digit<0||digit>9) return;
    for (int r=0;r<5;r++) {
        const char *pat=digits[digit][r];
        for (int c=0;c<6;c++) if (pat[c]=='#') {
            if (bold) attron(A_BOLD);
            if (bold) attron(A_BLINK);
            attron(COLOR_PAIR(pair_bg));
            mvaddch(y+r,x+c,' ');
            attroff(COLOR_PAIR(pair_bg));
            if (bold) attroff(A_BLINK);
            if (bold) attroff(A_BOLD);
        }
    }
}
void draw_colon(int y,int x,int pair_bg,int pair_fg,int bold,int visible) {
    for (int r=0;r<5;r++) {
        if (colon_pat[r][0]!='#') continue;
        for (int c=0;c<2;c++) if (colon_pat[r][c]=='#') {
            if (visible) {
                if (bold) attron(A_BOLD);
                if (bold) attron(A_BLINK);
                attron(COLOR_PAIR(pair_bg));
                mvaddch(y+r,x+c,' ');
                attroff(COLOR_PAIR(pair_bg));
                if (bold) attroff(A_BLINK);
                if (bold) attroff(A_BOLD);
            } else {
                if (bold) attron(A_BOLD);
                if (bold) attron(A_BLINK);
                attron(COLOR_PAIR(pair_fg));
                mvaddch(y+r,x+c,' ');
                attroff(COLOR_PAIR(pair_fg));
                if (bold) attroff(A_BLINK);
                if (bold) attroff(A_BOLD);
            }
        }
    }
}
void draw_clock_at(int y,int x,struct tm *tm,int blink_vis) {
    int hour=tm->tm_hour;
    if (opts.twelve) {
        int h=hour%12;
        if (h==0) h=12;
        hour=h;
    }
    int col=(opts.color>=0&&opts.color<=7)?opts.color:2;
    int pair_bg=col+1;
    int pair_fg=col+10;
    int ht=hour/10, ho=hour%10, mt=tm->tm_min/10, mo=tm->tm_min%10, st=tm->tm_sec/10, so=tm->tm_sec%10;
    if (opts.show_seconds) {
        draw_digit(y,x+0,ht,pair_bg,opts.bold);
        draw_digit(y,x+7,ho,pair_bg,opts.bold);
        draw_colon(y,x+15,pair_bg,pair_fg,opts.bold,blink_vis);
        draw_digit(y,x+19,mt,pair_bg,opts.bold);
        draw_digit(y,x+26,mo,pair_bg,opts.bold);
        draw_colon(y,x+34,pair_bg,pair_fg,opts.bold,blink_vis);
        draw_digit(y,x+38,st,pair_bg,opts.bold);
        draw_digit(y,x+45,so,pair_bg,opts.bold);
    } else {
        draw_digit(y,x+0,ht,pair_bg,opts.bold);
        draw_digit(y,x+7,ho,pair_bg,opts.bold);
        draw_colon(y,x+15,pair_bg,pair_fg,opts.bold,blink_vis);
        draw_digit(y,x+19,mt,pair_bg,opts.bold);
        draw_digit(y,x+26,mo,pair_bg,opts.bold);
    }
}
void draw_box_simple(int y,int x,int w,int h,int bold) {
    if (bold) attron(A_BOLD);
    mvaddch(y,x,ACS_ULCORNER);
    for (int i=1;i<w-1;i++) mvaddch(y,x+i,ACS_HLINE);
    mvaddch(y,x+w-1,ACS_URCORNER);
    for (int r=1;r<h-1;r++) {
        mvaddch(y+r,x,ACS_VLINE);
        mvaddch(y+r,x+w-1,ACS_VLINE);
    }
    mvaddch(y+h-1,x,ACS_LLCORNER);
    for (int i=1;i<w-1;i++) mvaddch(y+h-1,x+i,ACS_HLINE);
    mvaddch(y+h-1,x+w-1,ACS_LRCORNER);
    if (bold) attroff(A_BOLD);
}
void draw_box_with_date(int y,int x,int w,int h,const char *date_str,int bold,int pair_fg) {
    int date_len=strlen(date_str);
    int date_box_w=date_len+2;
    int remaining = (w-4) - date_len;
    int left_q = remaining/2;
    int right_q = remaining - left_q;
    if (left_q<0) left_q=0;
    if (right_q<0) right_q=0;
    if (bold) attron(A_BOLD);
    mvaddch(y,x,ACS_ULCORNER);
    for (int i=1;i<w-1;i++) mvaddch(y,x+i,ACS_HLINE);
    mvaddch(y,x+w-1,ACS_URCORNER);
    for (int r=1;r<h-1;r++) {
        mvaddch(y+r,x,ACS_VLINE);
        mvaddch(y+r,x+w-1,ACS_VLINE);
    }
    mvaddch(y+h-1,x,ACS_LLCORNER);
    for (int i=0;i<left_q;i++) mvaddch(y+h-1,x+1+i,ACS_HLINE);
    mvaddch(y+h-1,x+1+left_q,ACS_ULCORNER);
    for (int i=0;i<date_len;i++) mvaddch(y+h-1,x+1+left_q+1+i,ACS_HLINE);
    mvaddch(y+h-1,x+1+left_q+1+date_len,ACS_URCORNER);
    for (int i=0;i<right_q;i++) mvaddch(y+h-1,x+1+left_q+1+date_len+1+i,ACS_HLINE);
    mvaddch(y+h-1,x+w-1,ACS_LRCORNER);
    int dx=x+1+left_q;
    int dy=y+h-1;
    mvaddch(dy+1,dx,ACS_VLINE);
    mvaddch(dy+1,dx+date_box_w-1,ACS_VLINE);
    mvaddch(dy+2,dx,ACS_LLCORNER);
    for (int i=1;i<date_box_w-1;i++) mvaddch(dy+2,dx+i,ACS_HLINE);
    mvaddch(dy+2,dx+date_box_w-1,ACS_LRCORNER);
    if (bold) attroff(A_BOLD);
    if (bold) attron(A_BOLD);
    attron(COLOR_PAIR(pair_fg));
    mvaddstr(dy+1,dx+1,date_str);
    attroff(COLOR_PAIR(pair_fg));
    if (bold) attroff(A_BOLD);
}

void init_curses() {
    if (opts.tty_path) {
        struct stat st;
        if (stat(opts.tty_path,&st)!=0) {
            fprintf(stderr,"tty-clock: error: couldn't stat '%s': %s.\n",opts.tty_path,strerror(errno));
            exit(1);
        }
        if (!S_ISCHR(st.st_mode)) {
            fprintf(stderr,"tty-clock: error: '%s' doesn't appear to be a character device.\n",opts.tty_path);
            exit(1);
        }
        tty_out=fopen(opts.tty_path,"r+");
        if (!tty_out) {
            fprintf(stderr,"tty-clock: error: '%s' couldn't be opened: %s.\n",opts.tty_path,strerror(errno));
            exit(1);
        }
        ttyscr=newterm(NULL,tty_out,tty_out);
        if (!ttyscr) {
            fprintf(stderr,"%s: ttyclock.c:53: init: Assertion `ttyclock.ttyscr != NULL' failed.\n","executable");
            abort();
        }
        set_term(ttyscr);
    } else {
        // initscr will exit itself on failure printing Error opening terminal
        initscr();
    }
    cbreak();
    noecho();
    nodelay(stdscr,TRUE);
    keypad(stdscr,TRUE);
    curs_set(0);
    if (has_colors()) {
        start_color();
        for (int i=0;i<8;i++) {
            init_pair(i+1,COLOR_WHITE,i);
            init_pair(i+10,i,COLOR_BLACK);
        }
    }
    clear();
}

int main(int argc,char *argv[]) {
    setlocale(LC_ALL,"");
    memset(&opts,0,sizeof(opts));
    opts.color=-1;
    opts.delay_sec=1;
    opts.delay_nsec=0;
    int opt;
    while ((opt=getopt(argc,argv,"iuvsScbtrahDBxnC:f:d:a:T:"))!=-1) {
        switch(opt) {
            case 's': opts.show_seconds=1; break;
            case 'S': opts.screensaver=1; break;
            case 'x': opts.show_box=1; break;
            case 'c': opts.centered=1; break;
            case 'C': {
                char *end;
                long v=strtol(optarg,&end,10);
                if (end==optarg) opts.color=0;
                else if (v>=0&&v<=7) opts.color=v;
                break;
            }
            case 'b': opts.bold=1; break;
            case 't': opts.twelve=1; break;
            case 'u': opts.utc=1; break;
            case 'r': opts.rebound=1; break;
            case 'f': opts.date_format=optarg; break;
            case 'n': opts.noquit=1; break;
            case 'v': printf(VERSION_STR); return 0;
            case 'i': printf(INFO_STR); return 0;
            case 'h': printf("%s",usage_str); return 0;
            case 'D': opts.hide_date=1; break;
            case 'B': opts.blink=1; break;
            case 'd': {
                char *end;
                double dv=strtod(optarg,&end);
                if (end!=optarg) {
                    double intpart;
                    double frac=modf(dv,&intpart);
                    opts.delay_sec=(long)intpart;
                    opts.delay_nsec=(long)(frac*1e9);
                }
                break;
            }
            case 'a': {
                char *end;
                long v=strtol(optarg,&end,10);
                if (end!=optarg) {
                    // combine with existing fractional sec? Keep as is plus?
                    // For simplicity, if delay_sec fractional already set, add?
                    // We'll just set nsec to v plus existing fractional part?
                    // In original, -d and -a are additive? The description says additional delay.
                    // So we should add v to existing nsec from -d fractional.
                    long existing_frac = opts.delay_nsec % 1000000000;
                    // Actually we want total nsec = existing fractional + v
                    // But our parsing of -d already set delay_nsec to fractional part. So add.
                    opts.delay_nsec += v;
                    // Normalize
                    opts.delay_sec += opts.delay_nsec / 1000000000;
                    opts.delay_nsec %= 1000000000;
                }
                break;
            }
            case 'T': opts.tty_path=optarg; break;
            default: printf("%s",usage_str); return 0;
        }
    }
    compute_clock_size();
    init_curses();
    atexit(cleanup);
    getmaxyx(stdscr,term_h,term_w);
    if (opts.centered) {
        int total_w=opts.show_box?box_w:clock_w;
        int total_h=opts.show_box?box_h:clock_h;
        if (!opts.hide_date) total_h+= (opts.show_box?2:1);
        pos_x=(term_w-total_w)/2;
        pos_y=(term_h-total_h)/2;
        if (pos_x<0) pos_x=0;
        if (pos_y<0) pos_y=0;
    } else {
        pos_x=0; pos_y=0;
    }
    dir_x=1; dir_y=1;
    while (1) {
        time_t now=time(NULL);
        struct tm tm_now;
        if (opts.utc) gmtime_r(&now,&tm_now); else localtime_r(&now,&tm_now);
        int blink_vis=1;
        if (opts.blink) blink_vis=(tm_now.tm_sec%2==1);
        clear();
        int dy=pos_y, dx=pos_x;
        if (opts.show_box && opts.hide_date) {
            draw_box_simple(dy,dx,box_w,box_h,opts.bold);
            draw_clock_at(dy+1,dx+1,&tm_now,blink_vis);
        } else if (opts.show_box && !opts.hide_date) {
            char date_buf[512], tmp[512], ampm[32];
            const char *fmt=opts.date_format?opts.date_format:"%Y-%m-%d";
            strftime(tmp,sizeof(tmp),fmt,&tm_now);
            if (opts.twelve) {
                strftime(ampm,sizeof(ampm),"%p",&tm_now);
                snprintf(date_buf,sizeof(date_buf),"%s [%s]",tmp,ampm);
            } else snprintf(date_buf,sizeof(date_buf),"%s",tmp);
            int col=(opts.color>=0&&opts.color<=7)?opts.color:2;
            int pair_fg=col+10;
            int cur_box_w=box_w;
            int date_len=strlen(date_buf);
            int date_box_w=date_len+2;
            if (date_box_w>cur_box_w) cur_box_w=date_box_w+2;
            draw_box_with_date(dy,dx,cur_box_w,box_h,date_buf,opts.bold,pair_fg);
            draw_clock_at(dy+1,dx+1,&tm_now,blink_vis);
        } else {
            draw_clock_at(dy,dx,&tm_now,blink_vis);
            if (!opts.hide_date) {
                char date_buf[512], tmp[512], ampm[32];
                const char *fmt=opts.date_format?opts.date_format:"%Y-%m-%d";
                strftime(tmp,sizeof(tmp),fmt,&tm_now);
                if (opts.twelve) {
                    strftime(ampm,sizeof(ampm),"%p",&tm_now);
                    snprintf(date_buf,sizeof(date_buf),"%s [%s]",tmp,ampm);
                } else snprintf(date_buf,sizeof(date_buf),"%s",tmp);
                int date_len=strlen(date_buf);
                int date_x=dx+(clock_w-date_len)/2;
                int date_y=dy+clock_h;
                int col=(opts.color>=0&&opts.color<=7)?opts.color:2;
                int pair_fg=col+10;
                if (opts.bold) attron(A_BOLD);
                attron(COLOR_PAIR(pair_fg));
                mvaddstr(date_y,date_x,date_buf);
                attroff(COLOR_PAIR(pair_fg));
                if (opts.bold) attroff(A_BOLD);
            }
        }
        refresh();
        int ch=getch();
        if (ch!=ERR) {
            if (opts.screensaver && !opts.noquit) break;
            int lc=tolower(ch);
            if (lc=='q' && !opts.noquit) break;
            else if (lc=='c') {
                opts.centered=!opts.centered;
                if (opts.centered) {
                    int total_w=opts.show_box?box_w:clock_w;
                    int total_h=opts.show_box?box_h:clock_h;
                    if (!opts.hide_date) total_h+= (opts.show_box?2:1);
                    pos_x=(term_w-total_w)/2;
                    pos_y=(term_h-total_h)/2;
                    if (pos_x<0) pos_x=0;
                    if (pos_y<0) pos_y=0;
                }
            } else if (lc=='x') {
                opts.show_box=!opts.show_box;
                compute_clock_size();
                if (opts.centered) {
                    int total_w=opts.show_box?box_w:clock_w;
                    int total_h=opts.show_box?box_h:clock_h;
                    if (!opts.hide_date) total_h+= (opts.show_box?2:1);
                    pos_x=(term_w-total_w)/2;
                    pos_y=(term_h-total_h)/2;
                }
            } else if (lc=='b') opts.bold=!opts.bold;
            else if (lc>='0'&&lc<='7') { opts.color=lc-'0'; }
            else if (lc=='s') {
                opts.show_seconds=!opts.show_seconds;
                compute_clock_size();
                if (opts.centered) {
                    int total_w=opts.show_box?box_w:clock_w;
                    int total_h=opts.show_box?box_h:clock_h;
                    if (!opts.hide_date) total_h+= (opts.show_box?2:1);
                    pos_x=(term_w-total_w)/2;
                    pos_y=(term_h-total_h)/2;
                }
            } else if (lc=='t') opts.twelve=!opts.twelve;
            else if (lc=='r') opts.rebound=!opts.rebound;
            else if (lc=='h' && !opts.centered) { if (pos_x>0) pos_x--; }
            else if (lc=='l' && !opts.centered) {
                int cur_w=opts.show_box?box_w:clock_w;
                if (pos_x+cur_w < term_w) pos_x++;
            }
            else if (lc=='j' && !opts.centered) {
                int cur_h=opts.show_box?box_h:clock_h;
                if (!opts.hide_date) cur_h+= (opts.show_box?2:1);
                if (pos_y+cur_h < term_h) pos_y++;
            }
            else if (lc=='k' && !opts.centered) { if (pos_y>0) pos_y--; }
        }
        if (opts.rebound) {
            pos_x+=dir_x;
            pos_y+=dir_y;
            int cur_w=opts.show_box?box_w:clock_w;
            int cur_h=opts.show_box?box_h:clock_h;
            if (!opts.hide_date) cur_h+= (opts.show_box?2:1);
            if (pos_x<=0 || pos_x+cur_w>=term_w) { dir_x=-dir_x; pos_x+=dir_x; }
            if (pos_y<=0 || pos_y+cur_h>=term_h) { dir_y=-dir_y; pos_y+=dir_y; }
        }
        struct timespec ts;
        ts.tv_sec=opts.delay_sec;
        ts.tv_nsec=opts.delay_nsec;
        if (ts.tv_sec==0 && ts.tv_nsec==0) { ts.tv_sec=1; ts.tv_nsec=0; }
        nanosleep(&ts,NULL);
        getmaxyx(stdscr,term_h,term_w);
    }
    return 0;
}
