int main(int argc,char *argv[]){setlocale(LC_ALL,"");memset(&opts,0,sizeof(opts));opts.color=-1;opts.delay_sec=1;int opt;while((opt=getopt(argc,argv,"C:f:d:a:T:iuvsScbtrahDBxn"))!=-1){switch(opt){case 's':opts.show_seconds=1;break;case 'S':opts.screensaver=1;break;case 'x':opts.show_box=1;break;case 'c':opts.centered=1;break;case 'C':{char *end;long v=strtol(optarg,&end,10);if(end==optarg)opts.color=0;else if(v>=0&&v<=7)opts.color=v;break;}case 'b':opts.bold=1;break;case 't':opts.twelve=1;break;case 'u':opts.utc=1;break;case 'r':opts.rebound=1;break;case 'f':opts.date_format=optarg;break;case 'n':opts.noquit=1;break;case 'v':printf(VERSION_STR);return 0;case 'i':printf(INFO_STR);return 0;case 'h':printf("%s",usage_str);return 0;case 'D':opts.hide_date=1;break;case 'B':opts.blink=1;break;case 'd':{char *end;double dv=strtod(optarg,&end);if(end!=optarg){double ip;double fr=modf(dv,&ip);opts.delay_sec=(long)ip;opts.delay_nsec=(long)(fr*1e9);}break;}case 'a':{char *end;long v=strtol(optarg,&end,10);if(end!=optarg){opts.delay_nsec+=v;opts.delay_sec+=opts.delay_nsec/1000000000;opts.delay_nsec%=1000000000;}break;}case 'T':opts.tty_path=optarg;break;default:printf("%s",usage_str);return 0;}}compute_clock_size();init_curses();atexit(cleanup);getmaxyx(stdscr,term_h,term_w);if(opts.centered){int total_w=opts.show_box?box_w:clock_w;int total_h=opts.show_box?box_h:clock_h;if(!opts.hide_date)total_h+=(opts.show_box?2:1);pos_x=(term_w-total_w)/2;pos_y=(term_h-total_h)/2;if(pos_x<0)pos_x=0;if(pos_y<0)pos_y=0;}dir_x=1;dir_y=1;while(1){time_t now=time(NULL);struct tm tm_now;if(opts.utc)gmtime_r(&now,&tm_now);else localtime_r(&now,&tm_now);int blink_vis=1;if(opts.blink)blink_vis=(tm_now.tm_sec%2==1);clear();int dy=pos_y,dx=pos_x;if(opts.show_box&&opts.hide_date){draw_box_simple(dy,dx,box_w,box_h,opts.bold);draw_clock_at(dy+1,dx+1,&tm_now,blink_vis);}else if(opts.show_box&&!opts.hide_date){char date_buf[512],tmp[512],ampm[32];const char *fmt=opts.date_format?opts.date_format:"%Y-%m-%d";strftime(tmp,sizeof(tmp),fmt,&tm_now);if(opts.twelve){strftime(ampm,sizeof(ampm),"%p",&tm_now);snprintf(date_buf,sizeof(date_buf),"%s [%s]",tmp,ampm);}else snprintf(date_buf,sizeof(date_buf),"%s",tmp);int col=(opts.color>=0&&opts.color<=7)?opts.color:2;int pair_fg=col+10;int cur_box_w=box_w;int date_len=strlen(date_buf);int date_box_w=date_len+2;if(date_box_w>cur_box_w)cur_box_w=date_box_w+2;draw_box_with_date(dy,dx,cur_box_w,box_h,date_buf,opts.bold,pair_fg);draw_clock_at(dy+1,dx+1,&tm_now,blink_vis);}else{draw_clock_at(dy,dx,&tm_now,blink_vis);if(!opts.hide_date){char date_buf[512],tmp[512],ampm[32];const char *fmt=opts.date_format?opts.date_format:"%Y-%m-%d";strftime(tmp,sizeof(tmp),fmt,&tm_now);if(opts.twelve){strftime(ampm,sizeof(ampm),"%p",&tm_now);snprintf(date_buf,sizeof(date_buf),"%s [%s]",tmp,ampm);}else snprintf(date_buf,sizeof(date_buf),"%s",tmp);int date_len=strlen(date_buf);int date_x=dx+(clock_w-date_len)/2;int date_y=dy+clock_h;int col=(opts.color>=0&&opts.color<=7)?opts.color:2;int pair_fg=col+10;if(opts.bold)attron(A_BLINK);attron(COLOR_PAIR(pair_fg));mvaddstr(date_y,date_x,date_buf);attroff(COLOR_PAIR(pair_fg));if(opts.bold)attroff(A_BLINK);}}refresh();int ch=getch();if(ch!=ERR){if(opts.screensaver&&!opts.noquit)break;int lc=tolower(ch);if(lc=='q'&&!opts.noquit)break;else if(lc=='c'){opts.centered=!opts.centered;if(opts.centered){int total_w=opts.show_box?box_w:clock_w;int total_h=opts.show_box?box_h:clock_h;if(!opts.hide_date)total_h+=(opts.show_box?2:1);pos_x=(term_w-total_w)/2;pos_y=(term_h-total_h)/2;if(pos_x<0)pos_x=0;if(pos_y<0)pos_y=0;}}else if(lc=='x'){opts.show_box=!opts.show_box;compute_clock_size();if(opts.centered){int total_w=opts.show_box?box_w:clock_w;int total_h=opts.show_box?box_h:clock_h;if(!opts.hide_date)total_h+=(opts.show_box?2:1);pos_x=(term_w-total_w)/2;pos_y=(term_h-total_h)/2;}}else if(lc=='b')opts.bold=!opts.bold;else if(lc>='0'&&lc<='7')opts.color=lc-'0';else if(lc=='s'){opts.show_seconds=!opts.show_seconds;compute_clo