        draw_digit(y,x+0,ht,pair_bg,opts.bold);
        draw_digit(y,x+7,ho,pair_bg,opts.bold);
        draw_colon(y,x+15,pair_bg,pair_fg,opts.bold,blink_vis);
        draw_digit(y,x+19,mt,pair_bg,opts.bold);
        draw_digit(y,x+26,mo,pair_bg,opts.bold);
        draw_colon(y,x+34,pair_bg,pair_fg,opts.bold,blink_vis);
        draw_digit(y,x+38,st,pair_bg,opts.bold);
        draw_digit(y,x+45,so,pair_bg,opts.bold);
    } else {
        draw_digit(y,x+0,ht,pair_bg,opts.bold);
        draw_digit(y,x+7,ho,pair_bg,opts.bold);
        draw_colon(y,x+15,pair_bg,pair_fg,opts.bold,blink_vis);
        draw_digit(y,x+19,mt,pair_bg,opts.bold);
        draw_digit(y,x+26,mo,pair_bg,opts.bold);
    }
}
void draw_box_simple(int y,int x,int w,int h,int bold) {
    if (bold) attron(A_BLINK);
    mvaddch(y,x,ACS_ULCORNER);
    for (int i=1;i<w-1;i++) mvaddch(y,x+i,ACS_HLINE);
