}
void init_curses() {
    if (opts.tty_path) {
        struct stat st;
        if (stat(opts.tty_path,&st)!=0) {
            fprintf(stderr,"tty-clock: error: couldn't stat '%s': %s.\n",opts.tty_path,strerror(errno));
